function filtrarTruthy(lista) {
  return lista.filter(Boolean);
}

console.log(
  filtrarTruthy([0, "ola", "", null, 42, undefined, "0", NaN, [], {}])
);
// ["ola", 42, "0", [], {}]

function calcularMedia(valores) {
  const numeros = valores
    .map(Number)
    .filter((numero) => !Number.isNaN(numero));

  if (numeros.length === 0) {
    return 0;
  }

  const soma = numeros.reduce((acumulador, numero) => acumulador + numero, 0);
  return soma / numeros.length;
}

console.log(calcularMedia(["10", "abc", "20"])); // 15
console.log(calcularMedia(["x", "y"]));          // 0

exercises.statement:
A função abaixo pretende verificar se um id vindo de uma query string (que chega sempre como texto) corresponde a um id numérico guardado em memória, mas o uso de == provoca um comportamento incorreto nalguns casos:

function validarId(idQueryString, idGuardado) {
  return idQueryString == idGuardado;
}

Reescreva validarId para usar uma comparação explícita e estrita (sem ==), e explique num comentário um caso concreto em que a versão original com == validava um id que deveria ter sido rejeitado.

exercises.solution_code:
function validarId(idQueryString, idGuardado) {
  // idQueryString vem sempre como texto (ex.: de uma URL); convertemos
  // idGuardado para string, em vez do contrário, porque Number("")
  // resulta em 0 e reproduziria o mesmo bug da versão original.
  return String(idGuardado) === idQueryString;
}

// Caso problemático da versão original com ==:
// validarId("", 0) devolvia true com ==, porque "" é convertida para 0
// e 0 == 0, aceitando um id vazio como se fosse o id 0 (um bug silencioso).
console.log(validarId("", 0));    // false (agora rejeita corretamente)
console.log(validarId("42", 42)); // true

function saoValoresEquivalentes(a, b) {
  // NaN é o único valor que não é === a si próprio
  const ambosSaoNaN = a !== a && b !== b;
  if (ambosSaoNaN) {
    return true;
  }

  // === trata +0 e -0 como iguais; distinguimo-los pela divisão
  const ambosSaoZero = a === 0 && b === 0;
  if (ambosSaoZero) {
    return 1 / a === 1 / b;
  }

  return a === b;
}

console.log(saoValoresEquivalentes(NaN, NaN)); // true
console.log(saoValoresEquivalentes(0, -0));    // false
console.log(saoValoresEquivalentes(-0, -0));   // true
console.log(saoValoresEquivalentes(5, 5));     // true
console.log(saoValoresEquivalentes(5, "5"));   // false
